    const ajvPrototype = ((ajvModule as unknown as {default?: typeof ajvModule}).default ?? ajvModule).prototype;
    const compile = jest.spyOn(ajvPrototype, 'compile');
    try {
      const {registry} = registryWith({location: {type: 'string'}}, ['location']);

      for (let call = 0; call < 10; call++) await registry.execute('probe', {location: 'Berlin'});

